<?php
namespace App\Domain\Industries;use App\Models\{Industry,Page,Product,Solution};use Illuminate\Support\Facades\DB;use Illuminate\Validation\ValidationException;final class IndustryRelationManager{public function sync(Industry $industry,array $solutions,array $products,array $pages):void{foreach([[$solutions,8],[$products,8],[$pages,6]] as [$ids,$max]){if(count($ids)!==count(array_unique($ids))||count($ids)>$max){throw ValidationException::withMessages(['relations'=>'Relations must be unique and within their configured limit.']);}}if(Solution::whereIn('id',$solutions)->whereNotNull('archived_at')->exists()||Product::whereIn('id',$products)->whereNotNull('archived_at')->exists()||Page::whereIn('id',$pages)->whereNotNull('archived_at')->exists()){throw ValidationException::withMessages(['relations'=>'Archived targets cannot be selected.']);}DB::transaction(function()use($industry,$solutions,$products,$pages){foreach([['relatedSolutions',$solutions],['relatedProducts',$products],['relatedPages',$pages]] as [$relation,$ids]){$industry->{$relation}()->sync(collect($ids)->mapWithKeys(fn($id,$i)=>[$id=>['display_order'=>$i+1]])->all());}});IndustryCache::forget($industry->id);}}
